#!/usr/bin/env dotnet
#:sdk Microsoft.NET.Sdk #:package Avalonia@11.3.10 #:package Avalonia.Desktop@11.3.10 #:package Avalonia.ReactiveUI@11.3.9 #:package Avalonia.Markup.Xaml.Loader@11.3.10 #:package ReactiveUI@18.3.1 #:package ReactiveUI.Fody@18.3.1 #:property TargetFramework=net10.0 #:property Nullable=enable #:property ImplicitUsings=enable #:property UseWPF=false #:property UseWinUI=false  using Avalonia; using Avalonia.Controls; using Avalonia.Controls.ApplicationLifetimes; using Avalonia.Data; using Avalonia.Layout; using Avalonia.ReactiveUI; using ReactiveUI; using System; using System.Reactive; using System.Reactive.Disposables;  namespace SimpleAvaloniaApp {     public class MainViewModel : ReactiveObject     {         private string _greeting = "Hello, Avalonia!";         private int _counter = 0;         private bool _isDarkTheme = false;          public string Greeting         {             get => _greeting;             set => this.RaiseAndSetIfChanged(ref _greeting, value);         }          public int Counter         {             get => _counter;             set => this.RaiseAndSetIfChanged(ref _counter, value);         }          public bool IsDarkTheme         {             get => _isDarkTheme;             set => this.RaiseAndSetIfChanged(ref _isDarkTheme, value);         }          public ReactiveCommand<Unit, int> IncrementCommand { get; }         public ReactiveCommand<Unit, bool> ToggleThemeCommand { get; }          public MainViewModel()         {             IncrementCommand = ReactiveCommand.Create(() => Counter++);             ToggleThemeCommand = ReactiveCommand.Create(() => IsDarkTheme = !IsDarkTheme);         }     }      public class MainWindow : Window, IViewFor<MainViewModel>     {         public MainWindow()         {             // 创建UI组件             var grid = new Grid             {                 ColumnDefinitions = new ColumnDefinitions("*, 80"),                 RowDefinitions = new RowDefinitions("Auto, Auto, Auto"),                 Margin = new Thickness(20)             };              // 标题             var titleText = new TextBlock             {                 Text = "Avalonia Production App",                 FontSize = 24,                 FontWeight = Avalonia.Media.FontWeight.Bold,                 HorizontalAlignment = HorizontalAlignment.Center             };             Grid.SetColumn(titleText, 0);             Grid.SetColumnSpan(titleText, 2);             Grid.SetRow(titleText, 0);             grid.Children.Add(titleText);              // 问候语             var greetingText = new TextBlock             {                 Margin = new Thickness(0, 10, 0, 0)             };             Grid.SetColumn(greetingText, 0);             Grid.SetRow(greetingText, 1);             grid.Children.Add(greetingText);              // 计数器             var counterButton = new Button             {                 Content = "Increment",                 Margin = new Thickness(10, 10, 0, 0),                 HorizontalAlignment = HorizontalAlignment.Left             };             Grid.SetColumn(counterButton, 0);             Grid.SetRow(counterButton, 2);             grid.Children.Add(counterButton);              var counterText = new TextBlock             {                 Margin = new Thickness(10, 15, 0, 0),                 HorizontalAlignment = HorizontalAlignment.Left             };             Grid.SetColumn(counterText, 1);             Grid.SetRow(counterText, 2);             grid.Children.Add(counterText);              // 主题切换             var themeToggle = new CheckBox             {                 Content = "Dark Theme",                 Margin = new Thickness(0, 20, 0, 0),                 HorizontalAlignment = HorizontalAlignment.Center             };             Grid.SetColumn(themeToggle, 0);             Grid.SetColumnSpan(themeToggle, 2);             Grid.SetRow(themeToggle, 3);             grid.Children.Add(themeToggle);              Content = grid;             Width = 400;             Height = 300;             Title = "Avalonia Production App";              // 设置视图模型             ViewModel = new MainViewModel();              // 数据绑定             this.WhenActivated(disposables =>             {                 this.OneWayBind(ViewModel, vm => vm.Greeting, v => greetingText.Text)                     .DisposeWith(disposables);                 this.OneWayBind(ViewModel, vm => vm.Counter, v => counterText.Text)                     .DisposeWith(disposables);                 this.BindCommand(ViewModel, vm => vm.IncrementCommand, v => counterButton)                     .DisposeWith(disposables);                 this.Bind(ViewModel, vm => vm.IsDarkTheme, v => themeToggle.IsChecked)                     .DisposeWith(disposables);                 this.OneWayBind(ViewModel, vm => vm.IsDarkTheme, v => RequestedThemeVariant,                      isDark => isDark ? Avalonia.Styling.ThemeVariant.Dark : Avalonia.Styling.ThemeVariant.Light)                     .DisposeWith(disposables);             });         }          public MainViewModel ViewModel { get; set; }         object IViewFor.ViewModel { get => ViewModel; set => ViewModel = (MainViewModel)value; }     }      public class App : Application     {         public override void OnFrameworkInitializationCompleted()         {             if (ApplicationLifetime is IClassicDesktopStyleApplicationLifetime desktop)             {                 desktop.MainWindow = new MainWindow();             }              base.OnFrameworkInitializationCompleted();         }     }      public static class Program     {         public static void Main(string[] args)         {             BuildAvaloniaApp()                 .StartWithClassicDesktopLifetime(args, ShutdownMode.OnLastWindowClose);         }          public static AppBuilder BuildAvaloniaApp()         {             return AppBuilder.Configure<App>()                 .UsePlatformDetect()                 .LogToTrace()                 .UseReactiveUI();         }     } }
